    12→UGA_Jump::UGA_Jump()
    13→{
    14→	InstancingPolicy = EGameplayAbilityInstancingPolicy::InstancedPerActor;
    15→	NetExecutionPolicy = EGameplayAbilityNetExecutionPolicy::LocalPredicted;
    16→
    17→	FGameplayTagContainer AssetTags;
    18→	AssetTags.AddTag(WjWorldGameplayTag::Ability_Jump());
    19→	SetAssetTags(AssetTags);
    20→
    21→	// SpawnBrickPreview 또는 LiftBrickCarry 상태에서는 활성화 불가
    22→	ActivationBlockedTags.AddTag(WjWorldGameplayTag::State_SpawnBrickPreview());
    23→	ActivationBlockedTags.AddTag(WjWorldGameplayTag::State_LiftBrickCarry());
    24→
    25→	// 쿨다운 설정 (기본 없음, BP에서 설정 가능)
    26→	CooldownTags.AddTag(WjWorldGameplayTag::Cooldown_Jump());
    27→
    28→	// UI 메타데이터
    29→	AbilityName = NSLOCTEXT("Abilities", "Jump", "점프");
    30→}
    31→
    32→bool UGA_Jump::CanActivateAbility(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo, const FGameplayTagContainer* SourceTags, const FGameplayTagContainer* TargetTags, OUT FGameplayTagContainer* OptionalRelevantTags) const
    33→{
    34→	if (!Super::CanActivateAbility(Handle, ActorInfo, SourceTags, TargetTags, OptionalRelevantTags))
    35→	{
    36→		return false;
    37→	}
    38→
    39→	// 캐릭터가 점프 가능한 상태인지 확인 (바닥에 있는지 등)
    40→	const ACharacter* Character = CastChecked<ACharacter>(ActorInfo->AvatarActor.Get(), ECastCheckedType::NullAllowed);
    41→	return Character && Character->CanJump();
    42→}
    43→
    44→void UGA_Jump::ActivateAbility(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilityActivationInfo ActivationInfo, const FGameplayEventData* TriggerEventData)
    45→{
    46→	Super::ActivateAbility(Handle, ActorInfo, ActivationInfo, TriggerEventData);
    47→
    48→	if (HasAuthorityOrPredictionKey(ActorInfo, &ActivationInfo))
    49→	{
    50→		if (!CommitAbility(Handle, ActorInfo, ActivationInfo))
    51→		{
    52→			EndAbility(Handle, ActorInfo, ActivationInfo, true, true);
    53→			return;
    54→		}
    55→
    56→		ACharacter* Character = CastChecked<ACharacter>(ActorInfo->AvatarActor.Get());
    57→		Character->Jump();
    58→	}
    59→}
    60→
    61→void UGA_Jump::InputReleased(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilityActivationInfo ActivationInfo)
    62→{
    63→	if (ActorInfo && ActorInfo->AvatarActor.IsValid())
    64→	{
    65→		ACharacter* Character = CastChecked<ACharacter>(ActorInfo->AvatarActor.Get());
    66→		Character->StopJumping();
    67→	}
    68→
    69→	EndAbility(Handle, ActorInfo, ActivationInfo, true, false);
    70→}
    71→
    72→void UGA_Jump::CancelAbility(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo, const FGameplayAbilityActivationInfo ActivationInfo, bool bReplicateCancelAbility)
    73→{
    74→	if (ActorInfo && ActorInfo->AvatarActor.IsValid())
    75→	{
    76→		ACharacter* Character = CastChecked<ACharacter>(ActorInfo->AvatarActor.Get());
    77→		Character->StopJumping();
    78→	}
    79→
    80→	Super::CancelAbility(Handle, ActorInfo, ActivationInfo, bReplicateCancelAbility);
    81→}
    82→

