    69→{
    70→	bIsValid = bInIsValid;
    71→
    72→	if (DynamicMaterial)
    73→	{
    74→		FLinearColor Color = bIsValid ? ValidColor : InvalidColor;
    75→		DynamicMaterial->SetVectorParameterValue(TEXT("BaseColor"), Color);
    76→	}
