    60→void UPlacementHUDWidgetBase::PopulateCatalog(UWjWorldPlaceableObjectDataAsset* Catalog)
    61→{
    62→	if (!CatalogScrollBox || !Catalog)
    63→	{
    64→		return;
    65→	}
    66→
    67→	CatalogScrollBox->ClearChildren();
    68→	ButtonToObjectIdMap.Empty();
    69→
    70→	for (const FPlaceableObjectDefinition& Def : Catalog->Objects)
    71→	{
    72→		UButton* ItemButton = NewObject<UButton>(this);
    73→		UTextBlock* ItemText = NewObject<UTextBlock>(this);
    74→
    75→		ItemText->SetText(Def.DisplayName.IsEmpty() ? FText::FromName(Def.ObjectId) : Def.DisplayName);
    76→
    77→		// 버튼 스타일링
    78→		FSlateFontInfo FontInfo = ItemText->GetFont();
    79→		FontInfo.Size = 14;
    80→		ItemText->SetFont(FontInfo);
    81→
    82→		ItemButton->AddChild(ItemText);
    83→
    84→		// 버튼 → ObjectId 매핑 등록 + 공통 핸들러 바인딩
    85→		ButtonToObjectIdMap.Add(ItemButton, Def.ObjectId);
    86→		ItemButton->OnClicked.AddDynamic(this, &UPlacementHUDWidgetBase::OnCatalogButtonClicked);
    87→
    88→		CatalogScrollBox->AddChild(ItemButton);
    89→	}
    90→
    91→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetBase: Catalog populated with %d items"), Catalog->Objects.Num());
    92→}
