   108→void UPlacementHUDWidgetBase::OnSaveClicked()
   109→{
   110→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetBase: Save clicked"));
   111→
   112→	if (!SaveDialogClass)
   113→	{
   114→		// 다이얼로그 클래스가 없으면 기본 슬롯 이름으로 바로 저장
   115→		FString DefaultSlotName = GetCurrentLoadedSlotName();
   116→		if (DefaultSlotName.IsEmpty())
   117→		{
   118→			DefaultSlotName = GetSaveSlotNameForContext(GetCurrentContext());
   119→		}
   120→		ExecuteSave(DefaultSlotName);
   121→		return;
   122→	}
   123→
   124→	// 이미 열려있으면 스킵
   125→	if (SaveDialogInstance && SaveDialogInstance->IsInViewport())
   126→	{
   127→		return;
   128→	}
   129→
   130→	// 다이얼로그 생성
   131→	SaveDialogInstance = CreateWidget<UPlacementSaveDialogWidget>(GetOwningPlayer(), SaveDialogClass);
   132→	if (SaveDialogInstance)
   133→	{
   134→		// 로드된 슬롯 이름이 있으면 그것을 기본값으로, 없으면 컨텍스트 기본값 사용
   135→		FString DefaultSlotName = GetCurrentLoadedSlotName();
   136→		if (DefaultSlotName.IsEmpty())
   137→		{
   138→			DefaultSlotName = GetSaveSlotNameForContext(GetCurrentContext());
   139→		}
   140→		SaveDialogInstance->SetDefaultSlotName(DefaultSlotName);
   141→		SaveDialogInstance->SetContext(GetCurrentContext());
   142→
   143→		// 콜백 바인딩
   144→		SaveDialogInstance->OnSaveConfirmed.AddDynamic(this, &UPlacementHUDWidgetBase::OnSaveConfirmed);
   145→		SaveDialogInstance->ShowPopup();
   146→	}
   147→}
