   203→void UPlacementHUDWidgetBase::OnLoadClicked()
   204→{
   205→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetBase: Load clicked"));
   206→
   207→	if (!LoadDialogClass)
   208→	{
   209→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementHUDWidgetBase: LoadDialogClass not set"));
   210→		return;
   211→	}
   212→
   213→	// 이미 열려있으면 스킵
   214→	if (LoadDialogInstance && LoadDialogInstance->IsInViewport())
   215→	{
   216→		return;
   217→	}
   218→
   219→	// 다이얼로그 생성
   220→	LoadDialogInstance = CreateWidget<UPlacementLoadDialogWidget>(GetOwningPlayer(), LoadDialogClass);
   221→	if (LoadDialogInstance)
   222→	{
   223→		// 저장된 슬롯 목록 가져오기
   224→		TArray<FString> SlotNames;
   225→		if (PlacementComponent)
   226→		{
   227→			SlotNames = PlacementComponent->GetSavedLayoutSlots();
   228→		}
   229→
   230→		LoadDialogInstance->SetSlotList(SlotNames);
   231→		LoadDialogInstance->SetContext(GetCurrentContext());
   232→
   233→		// 콜백 바인딩
   234→		LoadDialogInstance->OnLoadConfirmed.AddDynamic(this, &UPlacementHUDWidgetBase::OnLoadConfirmed);
   235→		LoadDialogInstance->OnSlotDeleteRequested.AddDynamic(this, &UPlacementHUDWidgetBase::OnSlotDeleteRequested);
   236→		LoadDialogInstance->ShowPopup();
   237→	}
   238→}
