   246→void UPlacementHUDWidgetBase::ExecuteLoad(const FString& SlotName)
   247→{
   248→	// 기본 구현: PlacementComponent의 LoadLayoutFromSlot 호출
   249→	if (PlacementComponent)
   250→	{
   251→		if (PlacementComponent->LoadLayoutFromSlot(SlotName))
   252→		{
   253→			UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetBase: Layout loaded from slot '%s'"), *SlotName);
   254→		}
   255→		else
   256→		{
   257→			UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementHUDWidgetBase: Failed to load layout from slot '%s'"), *SlotName);
   258→		}
   259→	}
   260→}
   261→
   262→void UPlacementHUDWidgetBase::OnSlotDeleteRequested(const FString& SlotName)
   263→{
   264→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetBase: Slot delete requested: %s"), *SlotName);
   265→
   266→	if (PlacementComponent)
   267→	{
   268→		PlacementComponent->DeleteLayoutSlot(SlotName);
   269→
   270→		// 다이얼로그 내 슬롯 목록 갱신 (닫지 않음)
   271→		if (LoadDialogInstance)
   272→		{
   273→			TArray<FString> UpdatedSlots = PlacementComponent->GetSavedLayoutSlots();
   274→			LoadDialogInstance->SetSlotList(UpdatedSlots);
   275→		}
   276→	}
   277→}
