     8→/**
     9→ * 배치 컨텍스트 - 어떤 환경에서 배치하는지 구분
    10→ */
    11→UENUM(BlueprintType)
    12→enum class EPlacementContext : uint8
    13→{
    14→	None,
    15→	Lobby,              // 로비 데코레이션
    16→	ApproachingWall,    // Approaching Wall 벽 레이아웃 + 맵 데코
    17→	JumpMap             // JumpMap 플랫폼 + 장애물 + 함정
    18→};
    19→
    20→/**
    21→ * 컨텍스트별 SaveSlot 이름 반환
    22→ */
    23→inline FString GetSaveSlotNameForContext(EPlacementContext Context)
    24→{
    25→	switch (Context)
    26→	{
    27→	case EPlacementContext::Lobby:
    28→		return TEXT("LobbyLayout");
    29→	case EPlacementContext::ApproachingWall:
    30→		return TEXT("ApproachingWallLayout");
    31→	case EPlacementContext::JumpMap:
    32→		return TEXT("JumpMapLayout");
    33→	default:
    34→		return TEXT("DefaultLayout");
    35→	}
    36→}
    37→
    38→/**
    39→ * 컨텍스트 이름을 문자열로 반환 (디버그/로깅용)
    40→ */
    41→inline FString GetPlacementContextName(EPlacementContext Context)
    42→{
    43→	switch (Context)
    44→	{
    45→	case EPlacementContext::None:
    46→		return TEXT("None");
    47→	case EPlacementContext::Lobby:
    48→		return TEXT("Lobby");
    49→	case EPlacementContext::ApproachingWall:
    50→		return TEXT("ApproachingWall");
    51→	case EPlacementContext::JumpMap:
    52→		return TEXT("JumpMap");
    53→	default:
    54→		return TEXT("Unknown");
    55→	}
    56→}
    57→
    58→/**
    59→ * AW 컨텍스트용 벽돌 그리드 설정
    60→ */
    61→struct FApproachingWallGridConfig
    62→{
    63→	/** 벽돌 크기 (기본값 100x100x100) */
    64→	FVector BrickSize = FVector(100.0, 100.0, 100.0);
    65→
    66→	/** 그리드 원점 (중앙 기준) */
    67→	FVector GridOrigin = FVector::ZeroVector;
    68→
    69→	/** 최대 그리드 크기 */
    70→	int32 MaxGridRows = 20;
    71→	int32 MaxGridColumns = 20;
    72→};
    73→
    74→/**
    75→ * ObjectId를 CSV 벽돌 타입 값으로 변환
    76→ * @return -1=Empty, 1=Standard, 2=Explosive, 3=Moving, 4=Destructible
    77→ */
    78→inline int32 ObjectIdToBrickTypeValue(FName ObjectId)
    79→{
    80→	FString IdStr = ObjectId.ToString();
    81→
    82→	if (IdStr.Contains(TEXT("Standard")))
    83→	{
    84→		return 1;
    85→	}
    86→	else if (IdStr.Contains(TEXT("Explosive")))
    87→	{
    88→		return 2;
    89→	}
    90→	else if (IdStr.Contains(TEXT("Moving")))
    91→	{
    92→		return 3;
    93→	}
    94→	else if (IdStr.Contains(TEXT("Destructible")))
    95→	{
    96→		return 4;
    97→	}
    98→
    99→	// 기본값: Standard
   100→	return 1;
   101→}
