    68→
    69→	DestroyPreview();
    70→	UnbindInputActions();
    71→	SetComponentTickEnabled(false);
    72→
    73→	SelectedObjectId = NAME_None;
    74→	CurrentMode = EPlacementMode::None;
    75→	// 컨텍스트는 리셋하지 않음 (다음 EnterPlacementMode 시 설정)
