    81→void UWjWorldPlacementComponent::ToggleDeleteMode()
    82→{
    83→	if (CurrentMode == EPlacementMode::None)
    84→	{
    85→		return;
    86→	}
    87→
    88→	if (CurrentMode == EPlacementMode::Deleting)
    89→	{
    90→		// 삭제 모드 해제 → 배치 모드 복귀
    91→		if (HoveredObject)
    92→		{
    93→			HoveredObject->SetHighlighted(false);
    94→			HoveredObject = nullptr;
    95→		}
    96→		CurrentMode = EPlacementMode::Placing;
    97→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Switched to placing mode"));
    98→	}
    99→	else
   100→	{
   101→		// 배치 모드 → 삭제 모드
   102→		DestroyPreview();
   103→		CurrentMode = EPlacementMode::Deleting;
   104→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Switched to delete mode"));
   105→	}
   106→
   107→	OnPlacementModeChanged.Broadcast(CurrentMode);
   108→}
