   110→void UWjWorldPlacementComponent::SelectObject(FName ObjectId)
   111→{
   112→	if (!Catalog)
   113→	{
   114→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: No catalog set"));
   115→		return;
   116→	}
   117→
   118→	const FPlaceableObjectDefinition* Def = Catalog->FindByObjectId(ObjectId);
   119→	if (!Def)
   120→	{
   121→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: ObjectId=%s not found in catalog"), *ObjectId.ToString());
   122→		return;
   123→	}
   124→
   125→	// 삭제 모드에서 선택하면 배치 모드로 전환
   126→	if (CurrentMode == EPlacementMode::Deleting)
   127→	{
   128→		if (HoveredObject)
   129→		{
   130→			HoveredObject->SetHighlighted(false);
   131→			HoveredObject = nullptr;
   132→		}
   133→		CurrentMode = EPlacementMode::Placing;
   134→		OnPlacementModeChanged.Broadcast(CurrentMode);
   135→	}
   136→
   137→	// 기존 프리뷰 제거 후 새로 생성
   138→	DestroyPreview();
   139→	SelectedObjectId = ObjectId;
   140→
   141→	UWorld* World = GetWorld();
   142→	if (World)
   143→	{
   144→		FActorSpawnParameters SpawnParams;
   145→		SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
   146→		PreviewActor = World->SpawnActor<AWjWorldPlacementPreviewActor>(AWjWorldPlacementPreviewActor::StaticClass(), FVector::ZeroVector, FRotator::ZeroRotator, SpawnParams);
   147→		if (PreviewActor)
   148→		{
   149→			PreviewActor->InitializePreview(*Def);
   150→			UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Preview created for ObjectId=%s"), *ObjectId.ToString());
   151→		}
   152→	}
