   165→void UWjWorldPlacementComponent::ConfirmPlacement()
   166→{
   167→	if (CurrentMode != EPlacementMode::Placing || !PreviewActor || !bCurrentPreviewValid)
   168→	{
   169→		return;
   170→	}
   171→
   172→	if (!Catalog)
   173→	{
   174→		return;
   175→	}
   176→
   177→	const FPlaceableObjectDefinition* Def = Catalog->FindByObjectId(SelectedObjectId);
   178→	if (!Def)
   179→	{
   180→		return;
   181→	}
   182→
   183→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   184→	if (!DataProvider)
   185→	{
   186→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: PlacementDataProvider not found"));
   187→		return;
   188→	}
   189→
   190→	// 배치 데이터 생성
   191→	FVector SpawnLocation = PreviewActor->GetActorLocation();
   192→	FRotator SpawnRotation = FRotator(0.0f, PreviewActor->GetCurrentYaw(), 0.0f);
   193→
   194→	FPlacedObjectSaveEntry Entry;
   195→	Entry.ObjectId = SelectedObjectId;
   196→	Entry.Transform = FTransform(SpawnRotation, SpawnLocation, Def->DefaultScale);
   197→
   198→	// DataProvider에 추가 (서버에서 스폰 + 클라이언트 리플리케이션)
   199→	DataProvider->AddPlacedObject(Entry);
   200→
   201→	// 로컬 SaveGame에도 저장 (호스트 영구 저장용)
   202→	SaveLayout();
   203→
   204→	OnObjectPlaced.Broadcast();
   205→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Object placed - ObjectId=%s at %s (Context: %s)"),
   206→		*SelectedObjectId.ToString(), *SpawnLocation.ToString(), *GetPlacementContextName(CurrentContext));
   207→}
