   209→void UWjWorldPlacementComponent::DeleteHoveredObject()
   210→{
   211→	if (CurrentMode != EPlacementMode::Deleting || !HoveredObject)
   212→	{
   213→		return;
   214→	}
   215→
   216→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   217→	if (!DataProvider)
   218→	{
   219→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: PlacementDataProvider not found"));
   220→		return;
   221→	}
   222→
   223→	// DataProvider에서 해당 오브젝트 인덱스 찾기
   224→	int32 Index = FindPlacedObjectIndex(HoveredObject);
   225→	if (Index == INDEX_NONE)
   226→	{
   227→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Could not find object index for deletion"));
   228→		return;
   229→	}
   230→
   231→	HoveredObject = nullptr;
   232→
   233→	// DataProvider에서 제거 (서버에서 파괴 + 클라이언트 리플리케이션)
   234→	DataProvider->RemovePlacedObjectAt(Index);
   235→
   236→	// 로컬 SaveGame에도 저장
   237→	SaveLayout();
   238→
   239→	OnObjectDeleted.Broadcast();
   240→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Object deleted at index %d"), Index);
   241→}
