   248→void UWjWorldPlacementComponent::SaveLayout()
   249→{
   250→	// 호스트(ListenServer 또는 Standalone)인 경우에만 SaveGame 저장
   251→	// 클라이언트가 저장하면 다른 세션의 배치물이 섞이는 문제 발생
   252→	UWorld* World = GetWorld();
   253→	if (!World)
   254→	{
   255→		return;
   256→	}
   257→
   258→	ENetMode NetMode = World->GetNetMode();
   259→	if (NetMode != NM_Standalone && NetMode != NM_ListenServer)
   260→	{
   261→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: SaveLayout skipped (not host)"));
   262→		return;
   263→	}
   264→
   265→	// DataProvider에서 데이터를 가져와 로컬 SaveGame에 저장 (호스트 영구 저장용)
   266→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   267→	if (!DataProvider)
   268→	{
   269→		return;
   270→	}
   271→
   272→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   273→		UGameplayStatics::CreateSaveGameObject(UWjWorldLayoutSaveGame::StaticClass())
   274→	);
   275→
   276→	if (!SaveGame)
   277→	{
   278→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacementComponent: Failed to create save game object"));
   279→		return;
   280→	}
   281→
   282→	// DataProvider의 배치 데이터 복사
   283→	SaveGame->PlacedObjects = DataProvider->GetPlacedObjects();
   284→
   285→	// 컨텍스트별 SaveSlot 이름 사용
   286→	FString SlotName = GetCurrentSaveSlotName();
   287→	if (UGameplayStatics::SaveGameToSlot(SaveGame, SlotName, 0))
   288→	{
   289→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Layout saved to '%s' (%d objects)"),
   290→			*SlotName, SaveGame->PlacedObjects.Num());
   291→	}
   292→	else
   293→	{
   294→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacementComponent: Failed to save layout to '%s'"), *SlotName);
   295→	}
   296→}
