   316→	{
   317→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: SaveLayoutToSlot skipped (not host)"));
   318→		return;
   319→	}
   320→
   321→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   322→	if (!DataProvider)
   323→	{
   324→		return;
   325→	}
   326→
   327→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   328→		UGameplayStatics::CreateSaveGameObject(UWjWorldLayoutSaveGame::StaticClass())
   329→	);
   330→
   331→	if (!SaveGame)
   332→	{
   333→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacementComponent: Failed to create save game object"));
   334→		return;
   335→	}
