   364→bool UWjWorldPlacementComponent::LoadLayoutFromSlot(const FString& SlotName)
   365→{
   366→	UWorld* World = GetWorld();
   367→	if (!World)
   368→	{
   369→		return false;
   370→	}
   371→
   372→	// SaveGame 로드
   373→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   374→		UGameplayStatics::LoadGameFromSlot(SlotName, 0)
   375→	);
   376→
   377→	if (!SaveGame)
   378→	{
   379→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Failed to load layout from '%s'"), *SlotName);
   380→		return false;
   381→	}
   382→
   383→	// 컨텍스트 검증 (다른 컨텍스트의 레이아웃 로드 방지)
   384→	if (SaveGame->SavedContext != EPlacementContext::None && SaveGame->SavedContext != CurrentContext)
   385→	{
   386→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Context mismatch - slot '%s' is for '%s', current context is '%s'"),
   387→			*SlotName, *GetPlacementContextName(SaveGame->SavedContext), *GetPlacementContextName(CurrentContext));
   388→		return false;
   389→	}
   390→
   391→	// DataProvider가 있으면 데이터 설정
   392→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   393→	if (DataProvider)
   394→	{
   395→		// 일괄 설정 (RespawnAllPlacedObjects가 한 번만 호출됨)
   396→		DataProvider->SetPlacedObjects(SaveGame->PlacedObjects);
   397→	}
   398→
   399→	LoadedSlotName = SlotName;
   400→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Layout loaded from '%s' (%d objects)"),
   401→		*SlotName, SaveGame->PlacedObjects.Num());
   402→	return true;
   403→}
