   405→TArray<FString> UWjWorldPlacementComponent::GetSavedLayoutSlots() const
   406→{
   407→	TArray<FString> SlotNames;
   408→
   409→	// SaveGame 디렉토리에서 모든 .sav 파일 검색
   410→	FString SaveDirectory = FPaths::ProjectSavedDir() / TEXT("SaveGames");
   411→
   412→	IFileManager& FileManager = IFileManager::Get();
   413→	TArray<FString> FoundFiles;
   414→	FileManager.FindFiles(FoundFiles, *SaveDirectory, TEXT("*.sav"));
   415→
   416→	for (const FString& FileName : FoundFiles)
   417→	{
   418→		// .sav 확장자 제거하여 슬롯 이름 추출
   419→		FString SlotName = FPaths::GetBaseFilename(FileName);
   420→
   421→		// SaveGame을 로드하여 컨텍스트 확인
   422→		UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   423→			UGameplayStatics::LoadGameFromSlot(SlotName, 0)
   424→		);
   425→
   426→		if (SaveGame && SaveGame->SavedContext == CurrentContext)
   427→		{
   428→			SlotNames.Add(SlotName);
   429→		}
   430→	}
   431→
   432→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Found %d saved layout slots for context '%s'"),
   433→		SlotNames.Num(), *GetPlacementContextName(CurrentContext));
   434→	return SlotNames;
   435→}
