   437→bool UWjWorldPlacementComponent::DeleteLayoutSlot(const FString& SlotName)
   438→{
   439→	// SaveGame 삭제
   440→	if (!UGameplayStatics::DeleteGameInSlot(SlotName, 0))
   441→	{
   442→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Failed to delete save slot '%s'"), *SlotName);
   443→		return false;
   444→	}
   445→
   446→	// AW 컨텍스트: CSV 파일도 삭제
   447→	if (CurrentContext == EPlacementContext::ApproachingWall)
   448→	{
   449→		FString CSVPath = GetUserWallLayoutDirectory() / SlotName + TEXT(".csv");
   450→		IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   451→		if (PlatformFile.FileExists(*CSVPath))
   452→		{
   453→			PlatformFile.DeleteFile(*CSVPath);
   454→			UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Deleted CSV '%s'"), *CSVPath);
   455→		}
   456→	}
   457→	// JumpMap 컨텍스트: CSV 파일도 삭제
   458→	else if (CurrentContext == EPlacementContext::JumpMap)
   459→	{
   460→		FString CSVPath = GetUserJumpMapLayoutDirectory() / SlotName + TEXT(".csv");
   461→		IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   462→		if (PlatformFile.FileExists(*CSVPath))
   463→		{
   464→			PlatformFile.DeleteFile(*CSVPath);
   465→			UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Deleted CSV '%s'"), *CSVPath);
   466→		}
   467→	}
   468→
   469→	// 현재 로드된 슬롯이면 초기화
   470→	if (LoadedSlotName == SlotName)
   471→	{
   472→		LoadedSlotName.Empty();
   473→	}
   474→
   475→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Deleted layout slot '%s'"), *SlotName);
   476→	return true;
   477→}
   478→
   479→bool UWjWorldPlacementComponent::ExportLayoutAsCSV(const FString& FileName)
   480→{
   481→	// AW 컨텍스트에서만 동작
   482→	if (CurrentContext != EPlacementContext::ApproachingWall)
   483→	{
   484→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportLayoutAsCSV: Only available in ApproachingWall context"));
   485→		return false;
   486→	}
   487→
   488→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   489→	if (!DataProvider)
   490→	{
   491→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportLayoutAsCSV: No data provider"));
   492→		return false;
   493→	}
   494→
   495→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
   496→	if (PlacedObjects.Num() == 0)
   497→	{
   498→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportLayoutAsCSV: No objects to export"));
   499→		return false;
   500→	}
   501→
   502→	// 그리드 설정 (기본값 사용, 추후 설정 가능하게 확장 가능)
   503→	const FApproachingWallGridConfig GridConfig;
   504→	const FVector& BrickSize = GridConfig.BrickSize;
   505→
   506→	// 1. 배치된 오브젝트의 바운딩 박스 계산
   507→	FVector MinBounds(FLT_MAX, FLT_MAX, FLT_MAX);
   508→	FVector MaxBounds(-FLT_MAX, -FLT_MAX, -FLT_MAX);
   509→
   510→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   511→	{
   512→		const FVector& Location = Entry.Transform.GetLocation();
   513→		MinBounds.X = FMath::Min(MinBounds.X, Location.X);
   514→		MinBounds.Y = FMath::Min(MinBounds.Y, Location.Y);
   515→		MaxBounds.X = FMath::Max(MaxBounds.X, Location.X);
   516→		MaxBounds.Y = FMath::Max(MaxBounds.Y, Location.Y);
   517→	}
   518→
   519→	// 2. 그리드 크기 계산 (+1 = 위치 개수, +2 = 양쪽 1셀 패딩)
   520→	int32 GridColumns = FMath::CeilToInt((MaxBounds.X - MinBounds.X) / BrickSize.X) + 1 + 2;
   521→	int32 GridRows = FMath::CeilToInt((MaxBounds.Y - MinBounds.Y) / BrickSize.Y) + 1 + 2;
   522→
   523→	// 최소 크기 보장
   524→	GridColumns = FMath::Max(GridColumns, 3);
   525→	GridRows = FMath::Max(GridRows, 3);
   526→
   527→	// 그리드 원점: MinBounds에서 1칸 앞 (패딩용, 오브젝트가 인덱스 1부터 매핑)
   528→	FVector GridOrigin = MinBounds - FVector(BrickSize.X, BrickSize.Y, 0.0f);
   529→
   530→	// 3. 그리드 초기화 (-1 = Empty)
   531→	TArray<TArray<int32>> Grid;
   532→	Grid.SetNum(GridRows);
   533→	for (int32 Row = 0; Row < GridRows; ++Row)
   534→	{
   535→		Grid[Row].SetNum(GridColumns);
   536→		for (int32 Col = 0; Col < GridColumns; ++Col)
   537→		{
   538→			Grid[Row][Col] = -1;
   539→		}
   540→	}
   541→
   542→	// 4. 오브젝트를 그리드에 매핑 (RoundToInt로 CalculateBrickGridIndex와 일치)
   543→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   544→	{
   545→		const FVector& Location = Entry.Transform.GetLocation();
   546→
   547→		// 월드 좌표 → 그리드 인덱스
   548→		int32 Col = FMath::RoundToInt((Location.X - GridOrigin.X) / BrickSize.X);
   549→		int32 Row = FMath::RoundToInt((Location.Y - GridOrigin.Y) / BrickSize.Y);
   550→
   551→		// 범위 체크
   552→		if (Row >= 0 && Row < GridRows && Col >= 0 && Col < GridColumns)
   553→		{
   554→			int32 BrickTypeValue = ObjectIdToBrickTypeValue(Entry.ObjectId);
   555→			Grid[Row][Col] = BrickTypeValue;
   556→		}
   557→	}
   558→
   559→	// 5. CSV 문자열 생성 (첫 줄에 메타데이터 포함)
   560→	FString CSVContent;
   561→
   562→	// ⭐ 메타데이터 헤더: CenterOffset 저장 (클라이언트 프리뷰 위치 동기화용)
   563→	// CalculateBrickPosition은 CenterOffset을 그리드 중심으로 사용하므로, 그리드 중심 좌표를 저장
   564→	FVector CenterOffset;
   565→	CenterOffset.X = GridOrigin.X + (GridColumns - 1) * 0.5f * BrickSize.X;
   566→	CenterOffset.Y = GridOrigin.Y + (GridRows - 1) * 0.5f * BrickSize.Y;
   567→	CenterOffset.Z = 0.0f;
   568→	CSVContent += FString::Printf(TEXT("#META:CenterOffset:%f,%f,%f\n"),
   569→		CenterOffset.X, CenterOffset.Y, CenterOffset.Z);
   570→
   571→	for (int32 Row = 0; Row < GridRows; ++Row)
   572→	{
   573→		for (int32 Col = 0; Col < GridColumns; ++Col)
   574→		{
   575→			CSVContent += FString::Printf(TEXT("%d"), Grid[Row][Col]);
   576→			if (Col < GridColumns - 1)
   577→			{
   578→				CSVContent += TEXT(",");
   579→			}
   580→		}
   581→		CSVContent += TEXT("\n");
   582→	}
   583→
   584→	// 6. 파일 저장
   585→	FString UserLayoutDir = GetUserWallLayoutDirectory();
   586→
   587→	// 디렉토리 생성
