   610→bool UWjWorldPlacementComponent::ExportJumpMapLayoutAsCSV(const FString& FileName)
   611→{
   612→	if (CurrentContext != EPlacementContext::JumpMap)
   613→	{
   614→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportJumpMapLayoutAsCSV: Only available in JumpMap context"));
   615→		return false;
   616→	}
   617→
   618→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   619→	if (!DataProvider)
   620→	{
   621→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportJumpMapLayoutAsCSV: No data provider"));
   622→		return false;
   623→	}
   624→
   625→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
   626→	if (PlacedObjects.Num() == 0)
   627→	{
   628→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportJumpMapLayoutAsCSV: No objects to export"));
   629→		return false;
   630→	}
   631→
   632→	// CSV 생성: 헤더 + 오브젝트 행
   633→	FString CSVContent;
   634→	CSVContent += FString::Printf(TEXT("#META:MapName:%s\n"), *FileName);
   635→	CSVContent += TEXT("ObjectId,PosX,PosY,PosZ,RotPitch,RotYaw,RotRoll,ScaleX,ScaleY,ScaleZ\n");
   636→
   637→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   638→	{
   639→		const FVector& Loc = Entry.Transform.GetLocation();
   640→		const FRotator Rot = Entry.Transform.GetRotation().Rotator();
   641→		const FVector& Scale = Entry.Transform.GetScale3D();
   642→
   643→		CSVContent += FString::Printf(TEXT("%s,%f,%f,%f,%f,%f,%f,%f,%f,%f\n"),
   644→			*Entry.ObjectId.ToString(),
   645→			Loc.X, Loc.Y, Loc.Z,
   646→			Rot.Pitch, Rot.Yaw, Rot.Roll,
   647→			Scale.X, Scale.Y, Scale.Z);
   648→	}
   649→
   650→	// 파일 저장
   651→	FString UserLayoutDir = GetUserJumpMapLayoutDirectory();
   652→	IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   653→	if (!PlatformFile.DirectoryExists(*UserLayoutDir))
   654→	{
   655→		PlatformFile.CreateDirectoryTree(*UserLayoutDir);
   656→	}
   657→
   658→	FString FilePath = UserLayoutDir / FileName + TEXT(".csv");
   659→	if (FFileHelper::SaveStringToFile(CSVContent, *FilePath))
   660→	{
   661→		LastExportedCSVPath = FilePath;
   662→		UE_LOG(LogWjWorldPlacement, Log, TEXT("ExportJumpMapLayoutAsCSV: Exported to '%s' (%d objects)"),
   663→			*FilePath, PlacedObjects.Num());
   664→		return true;
   665→	}
   666→
   667→	UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportJumpMapLayoutAsCSV: Failed to save '%s'"), *FilePath);
   668→	return false;
   669→}
