   752→bool UWjWorldPlacementComponent::IsPlacementLocationValid(const FVector& Location) const
   753→{
   754→	UWorld* World = GetWorld();
   755→	if (!World)
   756→	{
   757→		return false;
   758→	}
   759→
   760→	// AW 컨텍스트: 그리드 스냅 사용 시 더 작은 반경으로 정확히 같은 위치만 체크
   761→	// 일반 컨텍스트: 기존 겹침 반경 사용
   762→	float CheckRadius = (CurrentContext == EPlacementContext::ApproachingWall)
   763→		? GridOverlapCheckRadius
   764→		: OverlapCheckRadius;
   765→
   766→	// 겹침 체크: 기존 배치된 오브젝트와 겹치는지
   767→	TArray<FOverlapResult> Overlaps;
   768→	FCollisionQueryParams QueryParams;
   769→	QueryParams.AddIgnoredActor(GetOwner());
   770→	if (PreviewActor)
   771→	{
   772→		QueryParams.AddIgnoredActor(PreviewActor);
   773→	}
   774→
   775→	FCollisionShape SphereShape = FCollisionShape::MakeSphere(CheckRadius);
   776→	World->OverlapMultiByChannel(Overlaps, Location, FQuat::Identity, ECC_Visibility, SphereShape, QueryParams);
   777→
   778→	for (const FOverlapResult& Overlap : Overlaps)
   779→	{
   780→		if (Cast<AWjWorldPlacedObjectActor>(Overlap.GetActor()))
   781→		{
   782→			return false;
   783→		}
   784→	}
   785→
   786→	return true;
   787→}
