   789→FVector UWjWorldPlacementComponent::SnapToGrid(const FVector& Location) const
   790→{
   791→	// AW 그리드 설정 사용
   792→	const FApproachingWallGridConfig GridConfig;
   793→	const FVector& BrickSize = GridConfig.BrickSize;
   794→
   795→	// 그리드 스냅: 각 축을 BrickSize 단위로 반올림
   796→	FVector SnappedLocation;
   797→	SnappedLocation.X = FMath::RoundToFloat(Location.X / BrickSize.X) * BrickSize.X;
   798→	SnappedLocation.Y = FMath::RoundToFloat(Location.Y / BrickSize.Y) * BrickSize.Y;
   799→	SnappedLocation.Z = Location.Z; // Z축은 스냅하지 않음 (바닥 높이 유지)
   800→
   801→	return SnappedLocation;
   802→}
