  1044→int32 UWjWorldPlacementComponent::FindPlacedObjectIndex(AWjWorldPlacedObjectActor* Actor) const
  1045→{
  1046→	if (!Actor)
  1047→	{
  1048→		return INDEX_NONE;
  1049→	}
  1050→
  1051→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
  1052→	if (!DataProvider)
  1053→	{
  1054→		return INDEX_NONE;
  1055→	}
  1056→
  1057→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
  1058→	FName TargetId = Actor->GetObjectId();
  1059→	FVector TargetLocation = Actor->GetActorLocation();
  1060→
  1061→	// ObjectId와 위치로 매칭 (동일 ObjectId가 여러 개 있을 수 있으므로 위치도 체크)
  1062→	for (int32 i = 0; i < PlacedObjects.Num(); ++i)
  1063→	{
  1064→		const FPlacedObjectSaveEntry& Entry = PlacedObjects[i];
  1065→		if (Entry.ObjectId == TargetId)
  1066→		{
  1067→			// 위치가 가까우면 매치
  1068→			if (FVector::DistSquared(Entry.Transform.GetLocation(), TargetLocation) < 100.0f)
  1069→			{
  1070→				return i;
  1071→			}
  1072→		}
  1073→	}
  1074→
  1075→	return INDEX_NONE;
  1076→}
