   671→void UWjWorldPlacementComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
   672→{
   673→	Super::TickComponent(DeltaTime, TickType, ThisTickFunction);
   674→
   675→	if (CurrentMode == EPlacementMode::Placing && PreviewActor)
   676→	{
   677→		// 프리뷰 위치 갱신
   678→		FHitResult HitResult;
   679→		if (TraceGroundUnderMouse(HitResult))
   680→		{
   681→			const FPlaceableObjectDefinition* Def = Catalog ? Catalog->FindByObjectId(SelectedObjectId) : nullptr;
   682→			float GroundOffset = Def ? Def->GroundOffset : 0.0f;
   683→
   684→			FVector PlaceLocation = HitResult.ImpactPoint + FVector(0.0f, 0.0f, GroundOffset);
   685→
   686→			// AW 컨텍스트: 그리드 스냅 적용
   687→			if (CurrentContext == EPlacementContext::ApproachingWall)
   688→			{
   689→				PlaceLocation = SnapToGrid(PlaceLocation);
   690→			}
   691→
   692→			FRotator PlaceRotation = FRotator(0.0f, PreviewActor->GetCurrentYaw(), 0.0f);
   693→			PreviewActor->UpdatePreviewTransform(PlaceLocation, PlaceRotation);
   694→
   695→			// 유효성 검사
   696→			bCurrentPreviewValid = IsPlacementLocationValid(PlaceLocation);
   697→			PreviewActor->SetPreviewValid(bCurrentPreviewValid);
   698→		}
   699→		else
   700→		{
   701→			bCurrentPreviewValid = false;
   702→			PreviewActor->SetPreviewValid(false);
   703→		}
   704→	}
   705→	else if (CurrentMode == EPlacementMode::Deleting)
   706→	{
   707→		// 삭제 모드: 호버 대상 갱신
   708→		AWjWorldPlacedObjectActor* NewHovered = TraceForPlacedObject();
   709→
   710→		if (NewHovered != HoveredObject)
   711→		{
   712→			if (HoveredObject)
   713→			{
   714→				HoveredObject->SetHighlighted(false);
   715→			}
   716→			HoveredObject = NewHovered;
   717→			if (HoveredObject)
   718→			{
   719→				HoveredObject->SetHighlighted(true);
   720→			}
   721→		}
   722→	}
   723→}
