   725→bool UWjWorldPlacementComponent::TraceGroundUnderMouse(FHitResult& OutHit) const
   726→{
   727→	APlayerController* PC = GetPlayerController();
   728→	if (!PC)
   729→	{
   730→		return false;
   731→	}
   732→
   733→	FVector WorldLocation, WorldDirection;
   734→	if (!PC->DeprojectMousePositionToWorld(WorldLocation, WorldDirection))
   735→	{
   736→		return false;
   737→	}
   738→
   739→	FVector TraceEnd = WorldLocation + WorldDirection * TraceDistance;
   740→
   741→	FCollisionQueryParams QueryParams;
   742→	QueryParams.bTraceComplex = false;
   743→	QueryParams.AddIgnoredActor(GetOwner());
   744→	if (PreviewActor)
   745→	{
   746→		QueryParams.AddIgnoredActor(PreviewActor);
   747→	}
   748→
   749→	return GetWorld()->LineTraceSingleByChannel(OutHit, WorldLocation, TraceEnd, ECC_Visibility, QueryParams);
   750→}
